<template>
  <main class="ops-review-page"><header><div><p>密价运营中心</p><h1>{{ releasesMode?'资金转回审核':'权益申请审核' }}</h1><p>{{ releasesMode?'申请不冻结余额。批准时重新检查可用本金，双边资金流水与执行状态一同提交。':'审核依据代理确认的发布规则，开通、续期、升级和重新签约分别记录。' }}</p></div><div class="actions"><el-button :loading="loading" @click="load">刷新申请</el-button><el-button v-if="releasesMode&&['course-wallet:read:any','course-wallet:audit','course-wallet:release'].some(can)" @click="$router.push('/admin/course-wallets')">原专户资金与完整流水</el-button><el-button v-if="!releasesMode&&can('course-private-contract:review')" type="primary" @click="openAssign">指定代理套餐</el-button></div></header>
    <el-alert v-if="error" :title="error" type="error" :closable="false" show-icon /><el-card><el-form inline @submit.prevent="load"><el-form-item label="申请状态"><el-select v-model="status" aria-label="审核申请状态" clearable style="width:170px"><el-option v-for="value in (releasesMode?releaseStates:applicationStates)" :key="value" :value="value" :label="privateState(value)" /></el-select></el-form-item><el-form-item v-if="!releasesMode" label="代理UUID"><el-input v-model="userUid" aria-label="审核代理UUID" clearable placeholder="公开UUID" /></el-form-item><el-button native-type="submit" type="primary">查询</el-button></el-form></el-card>
    <el-card v-loading="loading"><el-empty v-if="!rows.length&&!loading" description="没有匹配的待处理记录" /><article v-for="row in rows" :key="row.id" class="review-row"><div class="row-title"><h2>{{ releasesMode?`申请转回 ¥${privateMoney(row.amount)}`:`${row.planName} · ${applicationType(row.applicationType)}` }}</h2><el-tag>{{ privateState(row.status) }}</el-tag></div><p>{{ row.username||'代理账户' }}<span v-if="row.userUid"> · {{ row.userUid }}</span><span v-if="releasesMode"> · 原课程专户 {{ row.walletId }}</span></p><p>原始申请：{{ releasesMode?row.reason:row.applicationReason }}</p><p v-if="row.reviewReason">审核意见：{{ row.reviewReason }}</p><p v-if="!releasesMode">{{ row.effectivePolicy==='NEXT_TERM'?'下一期生效':row.effectivePolicy==='ON_ACTIVATION'?'实际资金资格满足后生效':'申请独立审核即时生效' }}<span v-if="row.acknowledgeLegacyChange"> · 已确认原权益变化</span></p><p v-if="row.executedTransferId">已执行划转记录：{{ row.executedTransferId }}，不是待处理申请。</p><small>{{ privateDate(row.createdAt||row.submittedAt) }}</small><div class="actions"><el-button v-if="!releasesMode&&row.sourceTermId&&can('course-private-term:read')" @click="inspect(row.sourceTermId)">查看原周期依据</el-button><template v-if="row.status==='PENDING'"><el-button v-if="canApprove" type="primary" @click="openReview(row,'approve')">{{ releasesMode?'批准并转回本金':'审核通过' }}</el-button><el-button v-if="canReject" type="danger" plain @click="openReview(row,'reject')">拒绝申请</el-button><el-button v-if="!releasesMode&&row.applicationType==='RENEW'&&canGrant" type="warning" @click="openReview(row,'grant-renewal')">独立人工补授</el-button></template><el-button v-if="unknown[row.id]&&canApprove" @click="openReview(row,unknown[row.id].action)">核对原审核结果</el-button></div></article><el-pagination v-model:current-page="page" :page-size="20" :total="total" layout="total,prev,pager,next" @current-change="load" /></el-card>
    <el-dialog v-model="reviewVisible" :title="reviewAction==='grant-renewal'?'确认人工补授':releasesMode?'财务审核确认':'权益审核确认'" width="min(560px,95vw)" :close-on-click-modal="!busy" :show-close="!busy"><p>{{ releasesMode?`原专户 ${selected?.walletId} · 申请金额 ¥${privateMoney(selected?.amount)}`:selected?.planName }}</p><el-alert :title="reviewAction==='reject'?'拒绝申请不产生资金划转或新权益。':reviewAction==='grant-renewal'?'只有原发布规则明确允许且独立权限齐备才可补授。保留原期未达标事实，不虚构预存或消费。':releasesMode?'将检查原拥有者、原专户及当前可用余额。批准成功才转回普通余额，余额不足会保留待处理状态。':'开通仍需满足真实资金门槛；续期和升级以冻结政策、资格及生效窗口核验，不能覆盖已确认的下一期。'" type="warning" :closable="false" show-icon /><el-form label-position="top"><el-form-item label="审核原因"><el-input v-model="reason" aria-label="运营审核原因" type="textarea" maxlength="255" :disabled="busy||recovering" /></el-form-item></el-form><el-alert v-if="formError" :title="formError" type="error" :closable="false" /><el-alert v-if="recovering" title="使用原记录和原版本核对，已成功执行的审批不会再转账或创建下一期。" type="info" :closable="false" /><template #footer><el-button :disabled="busy" @click="reviewVisible=false">取消</el-button><el-button type="primary" :loading="busy" @click="submitReview">{{ recovering?'核对原审核结果':'确认审核' }}</el-button></template></el-dialog>
    <el-dialog v-model="assignVisible" title="指定代理套餐申请" width="min(560px,95vw)" :close-on-click-modal="!busy" :show-close="!busy"><el-alert title="只使用公开代理UUID。指定形成待审核申请，不移动资金；重新签约或旧权益转换须代理本人明确提交。" type="info" :closable="false" show-icon /><el-form label-position="top"><el-form-item label="代理公开UUID"><el-input v-model="assignment.userUid" aria-label="指定代理公开UUID" :disabled="busy" /></el-form-item><el-form-item label="已发布套餐"><el-select v-model="assignment.planId" aria-label="指定代理套餐" :disabled="busy" @change="chooseAssignedPlan"><el-option v-for="plan in assignPlans" :key="plan.id" :value="plan.id" :label="plan.planName" /></el-select></el-form-item><p v-if="assignedVersion">确认已发布固定价 ¥{{ privateMoney(assignedVersion.fixedPrice) }}/单，首次本金 ¥{{ privateMoney(assignedVersion.initialDepositAmount) }}。</p><el-form-item label="申请类型"><el-select v-model="assignment.applicationType" aria-label="指定申请类型" :disabled="busy"><el-option value="OPEN" label="首次开通" /><el-option value="RENEW" label="原周期续期" /><el-option value="UPGRADE" label="同家族档位升级" /></el-select></el-form-item><el-form-item v-if="assignment.applicationType!=='OPEN'" label="来源周期编号"><el-input v-model="assignment.sourceTermId" aria-label="指定来源周期编号" inputmode="numeric" :disabled="busy" /></el-form-item><el-form-item label="指定原因"><el-input v-model="assignment.reason" aria-label="指定套餐原因" type="textarea" maxlength="255" :disabled="busy" /></el-form-item></el-form><el-alert v-if="formError" :title="formError" type="error" :closable="false" /><template #footer><el-button :disabled="busy" @click="assignVisible=false">取消</el-button><el-button type="primary" :loading="busy" @click="submitAssignment">确认指定申请</el-button></template></el-dialog>
    <el-dialog v-model="detailVisible" title="原周期及操作依据" width="min(880px,95vw)"><el-alert v-if="detailError" :title="detailError" type="error" :closable="false" /><div v-loading="detailLoading"><CoursePrivateTermDetails :is-admin="true" :detail="detail" @inspect="inspect" /></div></el-dialog>
  </main>
</template>
<script setup>
import {ref,reactive,computed,onMounted,watch} from 'vue';import {useRoute} from 'vue-router';import {ElMessage} from 'element-plus';import * as api from '@/api/coursePrivateOperations';import {sessionUserInfo} from '@/utils/authSession';import {hasPermission,hasAllPermissions,hasAnyPermission} from '@/utils/permissions';import {privateMoney,privateDate,privateState,createPrivateRequests} from '@/utils/coursePrivateOperations';import CoursePrivateTermDetails from '@/components/CoursePrivateTermDetails.vue';
const route=useRoute(),releasesMode=computed(()=>route.path.endsWith('/releases')),can=code=>hasPermission(sessionUserInfo.value,code),canApprove=computed(()=>releasesMode.value?hasAllPermissions(sessionUserInfo.value,['course-wallet-release:review','course-wallet:release']):can('course-private-contract:review')),canReject=computed(()=>releasesMode.value?can('course-wallet-release:review'):can('course-private-contract:review')),canGrant=computed(()=>hasAllPermissions(sessionUserInfo.value,['course-private-contract:review','course-private-term:adjust','course-private-settlement:execute']));
const applicationStates=['PENDING','APPROVED','REJECTED','CANCELLED'],releaseStates=['PENDING','EXECUTED','REJECTED','CANCELLED'],status=ref('PENDING'),userUid=ref(''),page=ref(1),total=ref(0),rows=ref([]),loading=ref(false),error=ref(''),busy=ref(false),unknown=reactive({});
const reviewVisible=ref(false),selected=ref(null),reviewAction=ref(''),reason=ref(''),recovering=ref(false),formError=ref(''),detailVisible=ref(false),detailLoading=ref(false),detailError=ref(''),detail=ref(null);let reviewVersion=0;const assignVisible=ref(false),assignPlans=ref([]),assignedVersion=ref(null),assignment=reactive({userUid:'',planId:null,planVersionId:null,sourceTermId:'',applicationType:'OPEN',reason:''});const requestKeys=createPrivateRequests({userUid:()=>sessionUserInfo.value?.uid});
const applicationType=value=>({OPEN:'首期开通',RENEW:'周期续期',UPGRADE:'档位升级',REJOIN:'终止后重新签约'}[value]||'权益申请');
async function load(){loading.value=true;error.value='';try{const params={page:page.value,pageSize:20};if(status.value)params.status=status.value;if(!releasesMode.value&&userUid.value.trim())params.userUid=userUid.value.trim();const response=await (releasesMode.value?api.getPrivateReleases(params,true):api.getPrivateApplications(params,true));rows.value=response.data.records||[];total.value=response.data.total||0;}catch(e){error.value=e.message||'审核列表读取失败';}finally{loading.value=false;}}
function openReview(row,action){if(busy.value)return;selected.value=row;reviewAction.value=action;formError.value='';const prior=unknown[row.id];recovering.value=!!prior;if(prior){reason.value=prior.reason;reviewVersion=prior.version;reviewAction.value=prior.action;}else{reason.value='';reviewVersion=row.version;}reviewVisible.value=true;}
async function submitReview(){if(busy.value)return;formError.value='';try{if(!reason.value.trim())throw new Error('请填写明确的审核依据');busy.value=true;const body={version:reviewVersion,reviewReason:reason.value.trim()},id=selected.value.id;unknown[id]={action:reviewAction.value,version:reviewVersion,reason:body.reviewReason};if(releasesMode.value)await api.reviewPrivateRelease(id,reviewAction.value==='approve',body);else await api.reviewPrivateApplication(id,reviewAction.value,body);delete unknown[id];reviewVisible.value=false;await load();ElMessage.success(reviewAction.value==='reject'?'申请已拒绝，资金未改变':'审核结果已确认，请以最新记录状态为准');}catch(e){formError.value=e.message||'结果未知，请刷新记录并核对原审核';recovering.value=!!unknown[selected.value?.id];}finally{busy.value=false;}}
async function openAssign(){if(busy.value)return;formError.value='';try{if(!hasAnyPermission(sessionUserInfo.value,['course-private-plan:read','course-private-plan:manage','course-private-plan:publish']))throw new Error('指定套餐需先具备套餐读取权限，以确认发布规则');assignPlans.value=(await api.getAdminPrivatePlans({page:1,pageSize:100,status:'PUBLISHED'})).data.records?.filter(plan=>plan.mode!=='LEGACY_PERMANENT')||[];Object.assign(assignment,{userUid:'',planId:null,planVersionId:null,sourceTermId:'',applicationType:'OPEN',reason:''});assignedVersion.value=null;assignVisible.value=true;}catch(e){ElMessage.error(e.message||'已发布套餐读取失败');}}
async function chooseAssignedPlan(id){try{const data=(await api.getAdminPrivatePlan(id)).data;assignedVersion.value=data.versions.find(version=>version.id===data.plan.currentVersionId);if(!assignedVersion.value)throw new Error('该套餐尚无已发布版本');assignment.planVersionId=assignedVersion.value.id;}catch(e){formError.value=e.message||'发布版本读取失败';}}
async function submitAssignment(){if(busy.value)return;formError.value='';try{if(!/^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$/i.test(assignment.userUid.trim())||!assignment.planVersionId||!assignment.reason.trim())throw new Error('请填写公开UUID、已发布套餐及明确原因');const body={userUid:assignment.userUid.trim(),planId:assignment.planId,planVersionId:assignment.planVersionId,applicationType:assignment.applicationType,sourceTermId:assignment.applicationType==='OPEN'?null:assignment.sourceTermId,effectivePolicy:assignment.applicationType==='OPEN'?'ON_ACTIVATION':'NEXT_TERM',acknowledgeLegacyChange:false,reason:assignment.reason.trim()};const scope=`assign:${body.userUid}:${body.planId}:${body.applicationType}`;const saved=requestKeys.begin(scope,body);busy.value=true;await api.submitPrivateApplication({...saved.body,requestKey:saved.requestKey},true);requestKeys.confirmed(scope,saved.requestKey);assignVisible.value=false;await load();ElMessage.success('指定申请已记录，尚待权益审核');}catch(e){formError.value=e.message||'结果未知，请核对原指定申请后用相同内容重试';}finally{busy.value=false;}}
async function inspect(id){detailVisible.value=true;detailLoading.value=true;detailError.value='';detail.value=null;try{detail.value=(await api.getPrivateTerm(id,true)).data;}catch(e){detailError.value=e.message||'原周期读取失败';}finally{detailLoading.value=false;}}
watch(releasesMode,()=>{page.value=1;status.value='PENDING';for(const key of Object.keys(unknown))delete unknown[key];load();});onMounted(load);
</script>
<style scoped>
.ops-review-page{display:grid;grid-template-columns:minmax(0,1fr);gap:18px;width:100%;box-sizing:border-box;max-width:1400px;margin:auto;padding:22px}.ops-review-page>*{min-width:0}.ops-review-page>header{display:flex;align-items:center;justify-content:space-between;gap:15px;flex-wrap:wrap}header>div{min-width:0}h1{font-size:26px;margin:5px 0 10px}header p,p,small{color:var(--el-text-color-secondary)}header p{margin:0}.review-row{padding:20px 0;border-bottom:1px solid var(--el-border-color-light);overflow-wrap:anywhere}.row-title{display:flex;align-items:center;gap:12px;flex-wrap:wrap}.row-title h2{font-size:18px;margin:0}.actions{display:flex;gap:8px;flex-wrap:wrap;margin-top:12px}.actions .el-button{margin:0}.el-pagination{overflow:auto;margin-top:18px}.el-input{max-width:100%}@media(max-width:600px){.ops-review-page{padding:12px}.el-form--inline .el-form-item{display:block}h1{font-size:23px}}
</style>
